section.section:
  PDO::FETCH_SERIALIZE (int)
  &warn.deprecated.feature-8-1-0;

   Questa modalità di fetch può essere utilizzata solo in combinazione con
   PDO::FETCH_CLASS (e con
   le sue altre opzioni).


   Quando si utilizza questa modalità di fetch, la classe specificata deve
   implementare Serializable.



    Questa funzionalità non supporta una stringa che contenga un oggetto
    serializzato completo (con serialize).




    Questa modalità di fetch non chiama il costruttore.





<?php
class TestEntity implements Serializable
{
    public $userid;

    public $name;

    public $country;

    public $referred_by_userid;

    public function __construct()
    {
        print "Costruttore chiamato con " . count(func_get_args()) . " argomenti\n";
        print "Proprietà impostate alla chiamata del costruttore? "
            . (isset($this->name) ? 'Sì' : 'No') . "\n";
    }

    public function serialize()
    {
        return join(
            "|",
            [$this->userid, $this->name, $this->country, $this->referred_by_userid]
        );
    }

    public function unserialize(string $data)
    {
        $parts = explode("|", $data);
        $this->userid = (int) $parts[0];
        $this->name = $parts[1];
        $this->country = $parts[2];

        $refId = $parts[3];
        $this->referred_by_userid = ($refId === "" ? null : (int) $refId);
    }
}

print "Preparazione del record (costruttore chiamato manualmente):\n";
$db->exec(
    "CREATE TABLE serialize (
        sdata TEXT
    )"
);

$origObj = new TestEntity();
$origObj->userid = 200;
$origObj->name = 'Seri';
$origObj->country = 'Syria';
$origObj->referred_by_userid = null;

$insert = $db->prepare("INSERT INTO serialize (sdata) VALUES (:sdata)");
$insert->execute(['sdata' => $origObj->serialize()]);

print "\nRecupero del risultato:\n";
$query = "SELECT sdata FROM serialize";
$stmt = $db->query($query);
// NOTA: il costruttore non viene mai chiamato!
$stmt->setFetchMode(PDO::FETCH_CLASS | PDO::FETCH_SERIALIZE, TestEntity::class);
$result = $stmt->fetch();
var_dump($result);


   &example.outputs.similar;


